import { getJson } from '../../api/http';

/** `today` is the sheet's own date (yyyy-mm-dd): use it, never the real clock, for anything dated. */
export type Sheet = { id: string; today: string };

/** Every query kept per sheet lives under this key, so re-loading a sheet re-reads all of it. */
export const sheetKey = (sheetId: string) => ['sheet', sheetId] as const;

export const sheetQuery = (sheetId: string) => ({
  queryKey: sheetKey(sheetId),
  queryFn: () => getJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}`),
});
import { useQuery } from '@tanstack/react-query';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { forSlot } from '../../slots/registry';
import { useSheetId } from './useSheetId';
import { sheetQuery } from './sheetQuery';

/** The loaded sheet: its id, then every per-sheet panel. Nothing shows until it has loaded. */
export function ActiveSheet({ user }: { user: string }) {
  const [sheetId] = useSheetId();
  const sheet = useQuery({ ...sheetQuery(sheetId), enabled: sheetId !== '' });

  if (sheetId === '') return <p data-testid="sheet-none">No sheet loaded.</p>;
  if (sheet.isError) return <p data-testid="sheet-load-error">Could not load sheet {sheetId}.</p>;
  if (!sheet.data) return <p data-testid="sheet-loading">Loading…</p>;

  return (
    <section data-testid="sheet">
      <h2>
        Sheet <span data-testid="sheet-current-id">{sheet.data.id}</span>
      </h2>
      <SheetPanel.Slot user={user} sheetId={sheet.data.id} />
      {forSlot(SheetPanel.id).length === 0 && <p data-testid="home-empty">Nothing here yet.</p>}
    </section>
  );
}
import { defineSlot } from '../Slot';

/**
 * The body of the loaded sheet. Every feature kept per sheet contributes its own panel here; it
 * is rendered only once a sheet has loaded, with the signed-in user and that sheet's id.
 */
export const SheetPanel = defineSlot<{ user: string; sheetId: string }>('sheet.panel');
