import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { useUser } from '../session/useUser';
import { sheetKey } from './sheetQuery';
import { periodsKey } from '../periods/periodsQuery';
import type { Sheet } from './sheetQuery';
import { useSheetToday } from './useSheetToday';

function SheetToday({ sheetId }: { sheetId: string }) {
  const today = useSheetToday(sheetId);
  const queryClient = useQueryClient();
  const [typed, setTyped] = useState('');
  const [error, setError] = useState('');

  const [user] = useUser();
  const once = useSubmitOnce();

  const save = useMutation({
    mutationFn: (date: string) =>
      putJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}/today`, { today: date }, user),
    onSuccess: async (sheet) => {
      queryClient.setQueryData(sheetKey(sheetId), sheet);
      // The change may have closed periods past their grace days.
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) });
    },
    onError: () => setError('That is not a date (yyyy-mm-dd).'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    once(() => save.mutateAsync(typed.trim()));
  };

  return (
    <form data-testid="sheet-today-form" onSubmit={submit}>
      Today <strong data-testid="sheet-today">{today}</strong>{' '}
      <label>
        Change to{' '}
        <input
          data-testid="sheet-today-input"
          placeholder="yyyy-mm-dd"
          value={typed}
          onChange={(e) => {
            setTyped(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="sheet-today-save">
        Set today
      </button>
      {error && <p data-testid="sheet-error">{error}</p>}
    </form>
  );
}

// Keyed by sheet, so a typed date or an error never carries over to another sheet.
export const contribution = SheetPanel.fill({
  order: 0,
  Component: ({ sheetId }) => <SheetToday key={sheetId} sheetId={sheetId} />,
});
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { useSheetId } from './useSheetId';
import { sheetKey } from './sheetQuery';

export function SheetPicker() {
  const [sheetId, setSheetId] = useSheetId();
  const queryClient = useQueryClient();
  const [typed, setTyped] = useState(sheetId);
  const [error, setError] = useState('');

  const submit = (e: FormEvent) => {
    e.preventDefault();
    const id = typed.trim();
    if (id === '') {
      setError('Type a sheet id to load.');
      return;
    }
    setError('');
    // Loading a sheet always re-reads it from the store, even when it was loaded before.
    void queryClient.invalidateQueries({ queryKey: sheetKey(id) });
    setSheetId(id);
  };

  return (
    <form data-testid="sheet-form" onSubmit={submit}>
      <label>
        Sheet{' '}
        <input
          data-testid="sheet-id-input"
          value={typed}
          onChange={(e) => {
            setTyped(e.target.value);
            setError('');
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="sheet-load">
        Load
      </button>
      {error && <p data-testid="sheet-error">{error}</p>}
    </form>
  );
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A write refused because the record was saved by someone else since it was loaded (409). */
export class ConflictError extends Error {}

/** A write refused by a rule the screen cannot see in full (422), e.g. a claim dated in a closed period; the message is the server's. */
export class RefusedError extends Error {}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (res.status === 409) {
    throw new ConflictError(`${init?.method ?? 'GET'} ${path} -> 409`);
  }
  if (res.status === 422) {
    throw new RefusedError(await res.text());
  }
  if (!res.ok) {
    throw new Error(`${init?.method ?? 'GET'} ${path} -> ${res.status}`);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

// A write names the signed-in user (X-User) so the server can record who made the change.
function jsonHeaders(user?: string): HeadersInit {
  return user ? { 'Content-Type': 'application/json', 'X-User': user } : { 'Content-Type': 'application/json' };
}

export function postJson<T>(path: string, body: unknown, user?: string): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: jsonHeaders(user),
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown, user?: string): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: jsonHeaders(user),
    body: JSON.stringify(body),
  });
}
import { useRef } from 'react';

/**
 * Guard a form's submit so a second submit while the first is still unanswered (a double click)
 * sends nothing. The guard is a ref, set synchronously, so it holds before React re-renders the
 * button as disabled.
 *
 *     const once = useSubmitOnce();
 *     once(() => save.mutateAsync(body));
 */
export function useSubmitOnce() {
  const busy = useRef(false);
  return (run: () => Promise<unknown>) => {
    if (busy.current) return;
    busy.current = true;
    run()
      .catch(() => undefined) // the mutation's onError shows the refusal
      .finally(() => {
        busy.current = false;
      });
  };
}
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}

